create table if not exists subscription_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),name text not null,description text,price numeric(12,2) not null default 0,interval text not null default 'month' check(interval in('month','year','one_time')),active boolean not null default true,features jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists subscribers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),company_id uuid references crm_companies(id),name text not null,email text,phone text,status text not null default 'lead' check(status in('lead','active','past_due','cancelled','inactive')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists coupons(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),code text not null,discount_type text not null check(discount_type in('percent','fixed')),discount_value numeric(12,2) not null check(discount_value>=0),starts_at timestamptz,ends_at timestamptz,max_redemptions integer,redemptions integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,code));
create table if not exists subscriptions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),subscriber_id uuid not null references subscribers(id),plan_id uuid not null references subscription_plans(id),status text not null default 'pending' check(status in('pending','active','past_due','cancelled','expired')),starts_at timestamptz,ends_at timestamptz,cancelled_at timestamptz,external_customer_id text,external_subscription_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists checkout_orders(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),subscriber_id uuid references subscribers(id),plan_id uuid references subscription_plans(id),coupon_id uuid references coupons(id),status text not null default 'draft' check(status in('draft','pending','paid','failed','cancelled','refunded')),subtotal numeric(12,2) not null default 0,discount numeric(12,2) not null default 0,total numeric(12,2) not null default 0,currency text not null default 'BRL',provider text,external_order_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists payment_webhook_events(id uuid primary key default gen_random_uuid(),organization_id uuid references organizations(id),provider text not null,event_id text not null,event_type text,payload jsonb not null default '{}'::jsonb,processed_at timestamptz,created_at timestamptz not null default now(),unique(provider,event_id));
create table if not exists financial_entries(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),order_id uuid references checkout_orders(id),entry_type text not null check(entry_type in('income','expense')),category text,description text not null,amount numeric(12,2) not null check(amount>=0),status text not null default 'pending' check(status in('pending','paid','cancelled')),due_date date,paid_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists commissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),order_id uuid references checkout_orders(id),beneficiary_name text not null,beneficiary_ref text,commission_type text not null check(commission_type in('percent','fixed')),rate numeric(12,4),amount numeric(12,2) not null default 0,status text not null default 'pending' check(status in('pending','approved','paid','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_subscriptions_org_status on subscriptions(organization_id,status);create index if not exists idx_orders_org_status on checkout_orders(organization_id,status);create index if not exists idx_finance_org_status on financial_entries(organization_id,status);create index if not exists idx_commissions_org_status on commissions(organization_id,status);
alter table subscription_plans enable row level security;alter table subscribers enable row level security;alter table coupons enable row level security;alter table subscriptions enable row level security;alter table checkout_orders enable row level security;alter table payment_webhook_events enable row level security;alter table financial_entries enable row level security;alter table commissions enable row level security;
